mapper.select:
select c.C_Name_History as tendereeNameHistory, c.C_Name as tendereeName, c.C_Abbreviation as tendereeAbbName,
from Sec_Info sec left join SYS_Company c on c.C_ID=sec.Sec_Tenderee where sec.Sec_Id in
#{secId}

select mn.*
from Sec_Info_Budget mn
where mn.Sec_Id = #{secId}

select
mn.* from Sec_Project mn
where mn.Sec_Id=#{secId}

select c.C_Name_History as tendereeNameHistory, c.C_Name as tendereeName, c.C_Abbreviation as tendereeAbbName, c1.C_Name as secAgencyName, c1.C_Abbreviation as secAgencyAbbName, dp.D_Name as secContractingDepartmentName, sd.D_Bid_Time as dBidTime, sd.D_Location as dLocation, sfe.focusCount, sbp.is_new as isNew,
from Sec_Info sec left join SYS_Company c on c.C_ID=sec.Sec_Tenderee left join SYS_Company c1 on c1.C_ID=sec.Sec_Agency left join SYS_Department dp on dp.D_ID=sec.Sec_Contracting_Department left join Sec_Bidding_Plan sbp on sbp.Bp_Id = sec.Bp_Id left join ( select sfe.sec_id, count(1) as focusCount from Sec_Focus_Expert sfe where sfe.state = 7 group by sfe.sec_id ) sfe on sfe.sec_id = sec.Sec_Id left join Sec_Document sd on sd.Sec_Id = sec.Sec_Id and sd.D_State = 7 AND sd.d_state_time = ( SELECT MAX(sd2.d_state_time) FROM Sec_Document sd2 WHERE sd2.Sec_Id = sec.Sec_Id AND sd2.D_State = 7 ) where sec.Sec_Id in (select sp.Sec_Id from Sec_Project sp left join Pre_Project pro on sp.P_ID=pro.P_Id where pro.P_Id=#{params.secPid} )
and (sec.Sec_Id in (select Sec_Id from Sec_Win_Notice where Wn_State=7
and Wn_Id in( select Wn_Id from Sec_Win_Unit where Wu_Company_Id=#{params.cId})
)
or sec.Sec_Bidding_Type='03'
)
and sec.Te_Id = #{params.teId}
and sec.Sec_Flow_State = #{params.secFlowState}
and sec.Sec_Name like concat('%',#{params.secName},'%')
and sec.isbd_Type = #{params.isbdType}
and sec.Sec_Bidding_Type = #{params.secBiddingType}
and sec.Sec_Section_Classify in
#{item}
and sec.Sec_Type in
#{tp}
and sec.Sec_Bidding_Type in
#{tp}
order by sec.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by sec.Sec_Create_Time DESC
limit #{params.start},#{params.size}

select
count(1)
from Sec_Info sec
left join SYS_Company c on c.C_ID=sec.Sec_Tenderee
where sec.Sec_Id in
(select sp.Sec_Id
from Sec_Project sp
left join Pre_Project pro on sp.P_ID=pro.P_Id
where pro.P_Id=#{params.secPid}
)

    and (sec.Sec_Id in (select Sec_Id from Sec_Win_Notice where Wn_State=7
    
        and Wn_Id in( select Wn_Id from Sec_Win_Unit where Wu_Company_Id=#{params.cId})
    
    )
    
        or sec.Sec_Bidding_Type='03'
    
    )


    and sec.Te_Id = #{params.teId}


    and sec.Sec_Flow_State = #{params.secFlowState}


    and sec.isbd_Type = #{params.isbdType}


    and sec.Sec_Name like concat('%',#{params.secName},'%')


    and sec.Sec_Bidding_Type = #{params.secBiddingType}


    and sec.Sec_Section_Classify in
    
        #{item}
    


    and sec.Sec_Type in
    
        #{tp}
    


    and sec.Sec_Bidding_Type in
    
        #{tp}

mapper.sql:

    and (
    (sec.Sec_Bidding_Type = '06' and
    (select c.C_Name
    from Sec_Inquiry_Record sir
    left join SYS_Company c on c.C_ID = sir.Sir_Intended_Unit
    where sir.Sec_Id = sec.Sec_Id
    and sir.State = 7
    order by sir.State_Time desc
    limit 1)
    like concat('%',#{params.unitName},'%'))
    or
    (sec.Sec_Bidding_Type != '06' and
    (select c.C_Name
    from Sec_Win_Notice wn
    left join Sys_Company c on c.C_Id = wn.Wn_Win_Unit
    where wn.Sec_Id = sec.Sec_Id
    and wn.Wn_State = 7
    order by wn.Wn_State_Time desc
    limit 1)
    like concat('%',#{params.unitName},'%')))


    and (
    (sec.Sec_Bidding_Type = '06' and
    (select sir.Sir_Con_Money from Sec_Inquiry_Record sir where sir.Sec_Id = sec.Sec_Id and sir.State = 7 order by sir.State_Time desc limit 1) = #{params.amount}
    )
    or
    (sec.Sec_Bidding_Type != '06' and
    (select wn.Wn_Amount from Sec_Win_Notice wn where wn.Sec_Id = sec.Sec_Id and wn.Wn_State = 7 order by wn.Wn_State_Time desc limit 1) = #{params.amount}
    ))


    and (
    (sec.Sec_Bidding_Type = '06' and
    (select sir.Sir_Con_Money from Sec_Inquiry_Record sir where sir.Sec_Id = sec.Sec_Id and sir.State = 7 order by sir.State_Time desc limit 1) >= #{params.amountStart}
    )
    or
    (sec.Sec_Bidding_Type != '06' and
    (select wn.Wn_Amount from Sec_Win_Notice wn where wn.Sec_Id = sec.Sec_Id and wn.Wn_State = 7 order by wn.Wn_State_Time desc limit 1) >= #{params.amountStart}
    ))


    and (
    (sec.Sec_Bidding_Type = '06' and
    (select sir.Sir_Con_Money from Sec_Inquiry_Record sir where sir.Sec_Id = sec.Sec_Id and sir.State = 7 order by sir.State_Time desc limit 1) <= #{params.amountEnd}
    )
    or
    (sec.Sec_Bidding_Type != '06' and
    (select wn.Wn_Amount from Sec_Win_Notice wn where wn.Sec_Id = sec.Sec_Id and wn.Wn_State = 7 order by wn.Wn_State_Time desc limit 1) <= #{params.amountEnd}
    ))



    and (
    (sec.Sec_Bidding_Type = '06' and
    (select sir.Sir_Evaluation_Time from Sec_Inquiry_Record sir where sir.Sec_Id = sec.Sec_Id and sir.State = 7 order by sir.State_Time desc limit 1) >= #{params.commentaryTimeStart}
    )
    or
    (sec.Sec_Bidding_Type != '06' and
    (select wn.Wn_Evaluation_Time from Sec_Win_Notice wn where wn.Sec_Id = sec.Sec_Id and wn.Wn_State = 7 order by wn.Wn_State_Time desc limit 1) >= #{params.commentaryTimeStart}
    ))


    and (
    (sec.Sec_Bidding_Type = '06' and
    (select sir.Sir_Evaluation_Time from Sec_Inquiry_Record sir where sir.Sec_Id = sec.Sec_Id and sir.State = 7 order by sir.State_Time desc limit 1) <= #{params.commentaryTimeEnd}
    )
    or
    (sec.Sec_Bidding_Type != '06' and
    (select wn.Wn_Evaluation_Time from Sec_Win_Notice wn where wn.Sec_Id = sec.Sec_Id and wn.Wn_State = 7 order by wn.Wn_State_Time desc limit 1) <= #{params.commentaryTimeEnd}
    ))


    and sec.Purchase_Number like concat('%',#{params.purchaseNumber},'%')


    and sec.Te_Id = #{params.teId}


    and sec.Sec_Year=#{params.secYear}


    and sec.Sec_Bidding_Type=#{params.secBiddingType}


    and sec.Sec_Con_Type=#{params.secConType}


    and sec.Bp_Id=#{params.bpId}


    and bp.State=#{params.bpState}


    and sec.Sec_Type=#{params.secType}


    and sec.Sec_Contracting_Type=#{params.secContractingType}


    and sec.Sec_Flow_State=#{params.secFlowState}


    and sec.Sec_Determin_Type=#{params.secDeterminType}


    and sec.Sec_Organize_Form=#{params.secOrganizeForm}


    and sec.Sec_Pricing_Method=#{params.secPricingMethod}


    and sec.Sec_Consortium=#{params.secConsortium}


    and sec.Sec_Subpackage=#{params.secSubpackage}


    and sec.Sec_Enterprise=#{params.secEnterprise}


    and sec.Sec_Import=#{params.secImport}


    and sec.Sec_Project_Nature=#{params.secProjectNature}


    and sec.Sec_Source_Fund=#{params.secSourceFund}


    and sec.Sec_Cost_Type!='02' and sec.Sec_Cost_Type!='03' and sec.Sec_Section_Classify!='/'


    and sec.Sec_Name like concat('%',#{params.secName},'%')


    and sec.Sec_Code like concat('%',#{params.secCode},'%')


    and sec.Sec_Create_Uname like concat('%',#{params.secCreateUname},'%')


    and sec.Sec_Approval_Title like concat('%',#{params.secApprovalTitle},'%')


    and sec.Sec_Approval_Num like concat('%',#{params.secApprovalNum},'%')


    and sec.Sec_Trading_Place like concat('%',#{params.secTradingPlace},'%')


    and sec.Sec_Place like concat('%',#{params.secPlace},'%')


    and sec.Sec_Remark like concat('%',#{params.secRemark},'%')


    
        
            and likeCname(#{params.tendereeName},c.C_Id)=true
        
        
            and c.C_Name like concat('%',#{params.tendereeName},'%')
        
    



    and sec.Sec_Bidding_Cycle>#{params.secBiddingCycleStart}


    and sec.Sec_Bidding_Cycle < #{params.secBiddingCycleEnd}


    and sec.Sec_Money>#{params.scMoneyStart}


    and sec.Sec_Money < #{params.scMoneyEnd}


    and sec.Sec_Start_Time>#{params.secStartTimeStart}


    and sec.Sec_Start_Time < #{params.secStartTimeEnd}


    and sec.Sec_End_Time>#{params.secEndTimeStart}


    and sec.Sec_End_Time < #{params.secEndTimeEnd}


    and sec.Sec_Create_Time>#{params.secCreateTimeStart}


    and sec.Sec_Create_Time < #{params.secCreateTimeEnd}


    and sec.Sec_Type  in
    
            #{tp}
    


    and sec.Sec_Bidding_Type in
    
         #{tp}
    


    ${params.excludeCancel}


    and sec.Sec_Con_Type in
    
        #{item}
    


    and sec.Sec_Id in (select Sec_Id from Sec_Win_Notice where Wn_State=7)


    and (select sum(
    case when sec.Sec_Bidding_Type='05' then (select count(*) from Sec_Price_Resultsf pr where pr.State=7 and pr.Sec_Id=sec.Sec_Id)
    else
    (case when sec.Sec_Bidding_Type='03' then (select count(*) from Sec_Entrust se where se.State=7 and se.Sec_Id=sec.Sec_Id)
    else  (select count(*) from Sec_Win_Notice wn where wn.Wn_State=7 and wn.Sec_Id=sec.Sec_Id) end )
    end
    )) > 0

and sec.Sec_Id in
(select mn.Sec_Id
from Sec_Project mn
left join Pre_Project pro on mn.P_ID=pro.P_Id

    ${params.authSql}


    where 1=1


    and pro.P_Id=#{params.secPid}


    and pro.P_Id=#{params.pId}


    and pro.P_Construction_Unit = #{params.cId}


    and pro.P_Build_Model = #{params.pBuildModel}


    and pro.P_Type = #{params.pType}


    and pro.P_Campus = #{params.pCampus}


    
        
            and likePname(#{params.pName},pro.P_Id)=true
        
    
    
        
            and pro.P_Name like concat('%',#{params.pName},'%')
        
    

)

mapper.select:
select c.C_Name_History as tendereeNameHistory, c.C_Name as tendereeName, c.C_Abbreviation as tendereeAbbName, c1.C_Name as secAgencyName, c1.C_Abbreviation as secAgencyAbbName, dp.D_Name as secContractingDepartmentName, u2.U_Name as secContactsName, u3.U_Name as secDelegateName,
case when sec.Sec_Bidding_Type = '06' then ( select sir.Sir_Con_Money from Sec_Inquiry_Record sir where sir.Sec_Id = sec.Sec_Id and sir.State = 7 order by sir.State_Time desc limit 1 ) else ( select wn.Wn_Amount from Sec_Win_Notice wn where wn.Sec_Id = sec.Sec_Id and wn.Wn_State = 7 order by wn.Wn_State_Time desc limit 1 ) end as amount, case when sec.Sec_Bidding_Type = '06' then ( select sir.Sir_Intended_Unit from Sec_Inquiry_Record sir where sir.Sec_Id = sec.Sec_Id and sir.State = 7 order by sir.State_Time desc limit 1 ) else ( select wn.Wn_Win_Unit from Sec_Win_Notice wn where wn.Sec_Id = sec.Sec_Id and wn.Wn_State = 7 order by wn.Wn_State_Time desc limit 1 ) end as unit, case when sec.Sec_Bidding_Type = '06' then ( select c.C_Name from Sec_Inquiry_Record sir left join SYS_Company c on c.C_ID = sir.Sir_Intended_Unit where sir.Sec_Id = sec.Sec_Id and sir.State = 7 order by sir.State_Time desc limit 1 ) else ( select c.C_Name from Sec_Win_Notice wn left join Sys_Company c on c.C_Id = wn.Wn_Win_Unit where wn.Sec_Id = sec.Sec_Id and wn.Wn_State = 7 order by wn.Wn_State_Time desc limit 1 ) end as unitName, case when sec.Sec_Bidding_Type = '06' then ( select sir.Sir_Evaluation_Time from Sec_Inquiry_Record sir where sir.Sec_Id = sec.Sec_Id and sir.State = 7 order by sir.State_Time desc limit 1 ) else ( select wn.Wn_Evaluation_Time from Sec_Win_Notice wn where wn.Sec_Id = sec.Sec_Id and wn.Wn_State = 7 order by wn.Wn_State_Time desc limit 1 ) end as commentaryTime, bp.State as bpState, (select wn.Wn_State from Sec_Win_Notice wn where wn.Sec_Id = sec.Sec_Id order by wn.Wn_State_Time desc limit 1) as wnState, (select wn.Wn_Id from Sec_Win_Notice wn where wn.Sec_Id = sec.Sec_Id order by wn.Wn_State_Time desc limit 1) as wnId,
from Sec_Info sec left join SYS_Company c on c.C_ID=sec.Sec_Tenderee left join SYS_Company c1 on c1.C_ID=sec.Sec_Agency left join SYS_Department dp on dp.D_ID=sec.Sec_Contracting_Department left join Sys_User u2 on u2.U_ID=sec.Sec_Contacts left join Sys_User u3 on u3.U_ID=sec.Sec_Delegate
inner join Sec_Bidding_Plan bp on bp.Bp_Id=sec.Bp_Id
left join Sec_Bidding_Plan bp on bp.Bp_Id=sec.Bp_Id
order by sec.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by sec.Sec_Create_Time DESC
limit #{params.start},#{params.size}

        select ifnull(sum(ls.secMoneyTotal),0)
        from (
        select
        mn.P_Id as pId,
        ifnull(cnt.secTotal,0) as secTotal,
        ifnull(amt.secMoneyTotal,0) as secMoneyTotal,
        amt.secCreateUname as secCreateUname
        from Pre_Project mn
        left join Sys_Department sd on sd.D_Id = mn.P_Competent_Department
        left join SYS_Company c11 on c11.C_Id = mn.P_Use_Unit
        inner join (
        select distinct sp.P_Id
        from Sec_Project sp
        
            left join Sec_Info sec on sec.Sec_Id = sp.Sec_Id
            left join Sec_Bidding_Plan sbp on sbp.Bp_Id = sec.Bp_Id
            where sec.Sec_Flow_State = #{params.state}
            
                and sbp.is_new = '1'
            
            
                and (sbp.is_new is null or sbp.is_new = '')
            
        
        ) ep on ep.P_Id = mn.P_Id
        left join (
        select
        sp.P_Id,
        count(1) as secTotal
        from Sec_Project sp
        inner join Sec_Info si on si.Sec_Id = sp.Sec_Id
        
            
                and si.Sec_Flow_State = #{params.state}
            
        
        group by sp.P_Id
        ) cnt on cnt.P_Id = mn.P_Id
        left join (
        select
        sp.P_Id,
        sum(si.Sec_Money) as secMoneyTotal,
        max(case
        when si.Sec_Create_Time = mx.maxCreateTime then si.Sec_Create_Uname
        end) as secCreateUname
        from Sec_Project sp
        inner join Sec_Info si on si.Sec_Id = sp.Sec_Id
        left join Sec_Bidding_Plan sbp on sbp.Bp_Id = si.Bp_Id
        left join (
        select
        sp2.P_Id,
        max(si2.Sec_Create_Time) as maxCreateTime
        from Sec_Project sp2
        inner join Sec_Info si2 on si2.Sec_Id = sp2.Sec_Id
        left join Sec_Bidding_Plan sbp2 on sbp2.Bp_Id = si2.Bp_Id
        
            
                and si2.Sec_Flow_State = #{params.state}
            
            
                and sbp2.is_new = '1'
            
            
                and (sbp2.is_new is null or sbp2.is_new = '')
            
        
        group by sp2.P_Id
        ) mx on mx.P_Id = sp.P_Id
        
            
                and si.Sec_Flow_State = #{params.state}
            
            
                and sbp.is_new = '1'
            
            
                and (sbp.is_new is null or sbp.is_new = '')
            
        
        group by sp.P_Id
        ) amt on amt.P_Id = mn.P_Id
        ${params.authSql}
        
            and mn.Te_Id = #{params.teId}
        
        
            and mn.P_Create_User_ID = #{params.pCreateUid}
        
        
            and mn.P_Build_Model = #{params.pBuildModel}
        
        
            and mn.P_Build_Model in
            
                #{item}
            
        
        
                and mn.P_Type = #{params.pType}
            
            
                and mn.P_Type in
                
                    #{item}
                
            
            
                and mn.P_Create_User_Name like concat('%',#{params.pCreateUname},'%')
            
            
                and sd.D_Name like concat('%',#{params.pCompetentDepartmentName},'%')
            
            
                and (mn.P_Use_Unit like concat('%',#{params.pUseUnit},'%')
                or c11.C_Name like concat('%',#{params.pUseUnit},'%'))
            
            
                and (mn.P_Use_Unit in
                
                    #{item}
                
                or c11.C_Name in
                
                    #{item}
                
                )
            
            
                and mn.P_Imp_Company like concat('%',#{params.pImpCompany},'%')
            
            
                and mn.P_Imp_Company in
                
                    #{item}
                
            
            
                
                    
                        and likePname(#{params.pName},mn.P_Id)=true
                    
                    
                        and mn.P_Name like concat('%',#{params.pName},'%')
                    
                
            
            
                and mn.P_Name in
                
                    #{item}
                
            
            
                and sd.D_Name in
                
                    #{item}
                
            
            
                and mn.P_Code like concat('%',#{params.pCode},'%')
            

            
                and ifnull(cnt.secTotal,0) >= #{params.secTotalStart}
            
            
                and ifnull(cnt.secTotal,0) <= #{params.secTotalEnd}
            
            
                and ifnull(amt.secMoneyTotal,0) >= #{params.secMoneyTotalStart}
            
            
                and ifnull(amt.secMoneyTotal,0) <= #{params.secMoneyTotalEnd}
            
            
                and amt.secCreateUname like concat('%',#{params.secCreateUname},'%')
            
        ) ls

select mn.P_Id as pId, mn.P_Name as pName, mn.P_Code as pCode, mn.P_Use_Unit as pUseUnit, ifnull(c11.C_Name, mn.P_Use_Unit) as pUseUnitName, mn.P_Imp_Company as pImpCompany, mn.P_Build_Model as pBuildModel, mn.P_Type as pType, ifnull(cnt.secTotal, 0) as secTotal, amt.secMoneyTotal as secMoneyTotal, amt.secCreateUname as secCreateUname, sd.D_Name as pCompetentDepartmentName, mn.P_Create_User_ID as pCreateUid, mn.P_Create_User_Name as pCreateUname from Pre_Project mn left join Sys_Department sd on sd.D_Id = mn.P_Competent_Department left join SYS_Company c11 on c11.C_Id = mn.P_Use_Unit inner join ( select distinct sp.P_Id from Sec_Project sp
left join Sec_Info sec on sec.Sec_Id = sp.Sec_Id left join Sec_Bidding_Plan sbp on sbp.Bp_Id = sec.Bp_Id where sec.Sec_Flow_State = #{params.state}
and sbp.is_new = '1'
and (sbp.is_new is null or sbp.is_new = '')
) ep on ep.P_Id = mn.P_Id left join ( select sp.P_Id, count(1) as secTotal from Sec_Project sp inner join Sec_Info si on si.Sec_Id = sp.Sec_Id
and si.Sec_Flow_State = #{params.state}
group by sp.P_Id ) cnt on cnt.P_Id = mn.P_Id left join ( select sp.P_Id, sum(si.Sec_Money) as secMoneyTotal, max(case when si.Sec_Create_Time = mx.maxCreateTime then si.Sec_Create_Uname end) as secCreateUname from Sec_Project sp inner join Sec_Info si on si.Sec_Id = sp.Sec_Id left join Sec_Bidding_Plan sbp on sbp.Bp_Id = si.Bp_Id left join ( select sp2.P_Id, max(si2.Sec_Create_Time) as maxCreateTime from Sec_Project sp2 inner join Sec_Info si2 on si2.Sec_Id = sp2.Sec_Id left join Sec_Bidding_Plan sbp2 on sbp2.Bp_Id = si2.Bp_Id
and si2.Sec_Flow_State = #{params.state}
and sbp2.is_new = '1'
and (sbp2.is_new is null or sbp2.is_new = '')
group by sp2.P_Id ) mx on mx.P_Id = sp.P_Id
and si.Sec_Flow_State = #{params.state}
and sbp.is_new = '1'
and (sbp.is_new is null or sbp.is_new = '')
group by sp.P_Id ) amt on amt.P_Id = mn.P_Id ${params.authSql}
and mn.Te_Id = #{params.teId}
and mn.P_Create_User_ID=#{params.pCreateUid}
and mn.P_Build_Model=#{params.pBuildModel}
and mn.P_Build_Model in
#{item}
and mn.P_Type=#{params.pType}
and mn.P_Type in
#{item}
and sd.P_Create_User_Name like concat('%',#{params.pCreateUname},'%')
and sd.D_Name like concat('%',#{params.pCompetentDepartmentName},'%')
and (mn.P_Use_Unit like concat('%',#{params.pUseUnit},'%') or c11.C_Name like concat('%',#{params.pUseUnit},'%'))
and (mn.P_Use_Unit in
#{item}
or c11.C_Name in
#{item}
)
and mn.P_Imp_Company like concat('%',#{params.pImpCompany},'%')
and mn.P_Imp_Company in
#{item}
and likePname(#{params.pName},mn.P_Id)=true
and mn.P_Name like concat('%',#{params.pName},'%')
and mn.P_Name in
#{item}
and mn.D_Name in
#{item}
and mn.P_Code like concat('%',#{params.pCode},'%')
and mn.P_Id in (select sp.P_Id from Sec_Project sp
left join Sec_Info sec on sp.Sec_Id=sec.Sec_Id left join Sec_Bidding_Plan sbp on sbp.Bp_Id = sec.Bp_Id where sec.Sec_Flow_State = #{params.state}
and sbp.is_new = '1'
and (sbp.is_new is null or sbp.is_new = '')
)
and ifnull(cnt.secTotal,0) >= #{params.secTotalStart}
and ifnull(cnt.secTotal,0) <= #{params.secTotalEnd}
and ifnull(amt.secMoneyTotal,0) >= #{params.secMoneyTotalStart}
and ifnull(amt.secMoneyTotal,0) <= #{params.secMoneyTotalEnd}
and amt.secCreateUname like concat('%',#{params.secCreateUname},'%')
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.P_Create_Time DESC

select * from Sec_Info si inner join Sec_Project sp on si.Sec_Id=sp.Sec_Id inner join Pre_Project pp on sp.P_Id=pp.P_Id
where pp.P_Id in
#{projectId}

select si.* from  Sec_Info si left join Sec_Project sp on si.Sec_Id=sp.Sec_Id

    
        and sp.p_id = #{params.projectId}
    
   
       and si.Sec_Name = #{params.isbdSectionName}
   
    
        and si.ie_id = #{params.ieId}
    
   
       and si.ie_detail_id = #{params.ieDetailId}
   
    
        and si.ib_id = #{params.ibId}
    
   
       and si.ib_detail_id = #{params.ibDetailId}
   

limit 1
